        colors: ["B"],
        imageUrl: "https://cards.scryfall.io/normal/front/f/e/fe85a124-0d8b-4a29-8df1-65888a39147f.jpg?1783903675",
        artCropUrl: "https://cards.scryfall.io/art_crop/front/f/e/fe85a124-0d8b-4a29-8df1-65888a39147f.jpg?1783903675",
        power: "1",
